-- English Physics Chapter 5: Physical Optics (61 supplied MCQs).
-- Keep question order, answer indices, and stable IDs in sync with
-- src/data/physicsChapter5EnglishMcqs.json, the frontend fallback.
WITH seed (id, section, question, choices, answer_index, sort_order) AS (
  VALUES
  ('502c974d-2f8a-48df-996f-000000000001'::uuid, 'Interference and Coherence', 'When two waves of equal amplitude meet in phase, the resulting amplitude is:', '["Zero","Equal to one wave","Twice the amplitude of one wave","Half the amplitude"]'::jsonb, 2, 1),
  ('502c974d-2f8a-48df-996f-000000000002'::uuid, 'Interference and Coherence', 'Destructive interference results from the overlap of:', '["Two crests","A crest and a trough","Two troughs","A crest and the equilibrium position"]'::jsonb, 1, 2),
  ('502c974d-2f8a-48df-996f-000000000003'::uuid, 'Interference and Coherence', 'The condition for constructive interference is:', '["Δℓ = (m + ½)λ","Δℓ = mλ","Δℓ = mλ/2","Δℓ = (2m + 1)λ/4"]'::jsonb, 1, 3),
  ('502c974d-2f8a-48df-996f-000000000004'::uuid, 'Interference and Coherence', 'The condition for destructive interference is:', '["Δℓ = (m + ½)λ","Δℓ = mλ","Δℓ = 2mλ","Δℓ = 0"]'::jsonb, 0, 4),
  ('502c974d-2f8a-48df-996f-000000000005'::uuid, 'Interference and Coherence', 'In constructive interference the phase difference φ equals:', '["π, 3π, 5π …","π/2, 3π/2 …","0, 2π, 4π …","Only zero"]'::jsonb, 2, 5),
  ('502c974d-2f8a-48df-996f-000000000006'::uuid, 'Interference and Coherence', 'If the optical path difference is λ/2, the phase difference is:', '["π/2","π","2π","0"]'::jsonb, 1, 6),
  ('502c974d-2f8a-48df-996f-000000000007'::uuid, 'Interference and Coherence', 'To obtain permanent interference in light, the sources must be:', '["Coherent","Incoherent","Of different colours","Of different amplitudes only"]'::jsonb, 0, 7),
  ('502c974d-2f8a-48df-996f-000000000008'::uuid, 'Interference and Coherence', 'Source S1 has optical path ℓ₁ = 2.25λ and S2 has ℓ₂ = 3.25λ to the same point. The interference is:', '["Destructive","Constructive","None","Partial polarization"]'::jsonb, 1, 8),
  ('502c974d-2f8a-48df-996f-000000000009'::uuid, 'Interference and Coherence', 'If ℓ₁ = 1λ and ℓ₂ = 1.5λ, the path difference is λ/2 and the interference is:', '["Constructive","Destructive","No interference","Polarization"]'::jsonb, 1, 9),
  ('502c974d-2f8a-48df-996f-000000000010'::uuid, 'Interference and Coherence', 'Two coherent sources (λ = 0.1 m) send waves along paths of 3.2 m and 3 m to point P. The interference at P is:', '["Destructive","Neither","Constructive","Cannot be determined"]'::jsonb, 2, 10),
  ('502c974d-2f8a-48df-996f-000000000011'::uuid, 'Interference and Coherence', 'Two incoherent sources do not give a stable interference pattern because:', '["They have the same frequency","The phase difference between them changes randomly with time","Their amplitude is zero","Their wavelengths are equal"]'::jsonb, 1, 11),
  ('502c974d-2f8a-48df-996f-000000000012'::uuid, 'Young''s Double Slit Experiment', 'The bright and dark fringes in Young''s experiment are caused by:', '["Diffraction only","Interference only","Diffraction and interference together","Polarization"]'::jsonb, 2, 12),
  ('502c974d-2f8a-48df-996f-000000000013'::uuid, 'Young''s Double Slit Experiment', 'The central fringe in Young''s experiment is always bright because:', '["Δℓ = λ/2","Δℓ = λ","Δℓ = 0","Δℓ = 3λ/2"]'::jsonb, 2, 13),
  ('502c974d-2f8a-48df-996f-000000000014'::uuid, 'Young''s Double Slit Experiment', 'With white light, the central fringe appears:', '["Red","Violet","White","Dark"]'::jsonb, 2, 14),
  ('502c974d-2f8a-48df-996f-000000000015'::uuid, 'Young''s Double Slit Experiment', 'Coloured fringes in Young''s experiment indicate that the light used is:', '["Monochromatic","Composite (white) light","Incoherent","Polarized"]'::jsonb, 1, 15),
  ('502c974d-2f8a-48df-996f-000000000016'::uuid, 'Young''s Double Slit Experiment', 'The fringe spacing is given by:', '["Δy = λd/L","Δy = λL/d","Δy = Ld/λ","Δy = λ/(Ld)"]'::jsonb, 1, 16),
  ('502c974d-2f8a-48df-996f-000000000017'::uuid, 'Young''s Double Slit Experiment', 'The fringe spacing increases when:', '["The screen distance L decreases","The slit separation d increases","The wavelength λ increases","The slits are made identical"]'::jsonb, 2, 17),
  ('502c974d-2f8a-48df-996f-000000000018'::uuid, 'Young''s Double Slit Experiment', 'Fringes with red light are wider than with blue light because:', '["Red has a longer wavelength","Red has a shorter wavelength","Red has a higher frequency","Red is not coherent"]'::jsonb, 0, 18),
  ('502c974d-2f8a-48df-996f-000000000019'::uuid, 'Young''s Double Slit Experiment', 'If Young''s experiment is carried out under water, the fringe spacing:', '["Increases","Decreases","Stays unchanged","Disappears"]'::jsonb, 1, 19),
  ('502c974d-2f8a-48df-996f-000000000020'::uuid, 'Young''s Double Slit Experiment', 'In Young''s experiment d = 0.2 mm, L = 1 m, and the third bright fringe is 9.49 mm from the centre. The wavelength is about:', '["450 nm","520 nm","633 nm","700 nm"]'::jsonb, 2, 20),
  ('502c974d-2f8a-48df-996f-000000000021'::uuid, 'Young''s Double Slit Experiment', 'Red light (664 nm), d = 1.2×10⁻⁴ m, L = 2.75 m. The distance of the third bright fringe from the centre is:', '["4.565 cm","1.52 cm","45.65 cm","0.4565 cm"]'::jsonb, 0, 21),
  ('502c974d-2f8a-48df-996f-000000000022'::uuid, 'Young''s Double Slit Experiment', 'Green light (5×10⁻⁷ m), d = 1 mm, L = 2 m. The distance between two successive bright fringes is:', '["0.1 mm","0.25 mm","0.4 mm","1 mm"]'::jsonb, 3, 22),
  ('502c974d-2f8a-48df-996f-000000000023'::uuid, 'Young''s Double Slit Experiment', 'L = 4.5 m, λ = 490 nm, and the first bright fringe is 4.5 cm from the centre. The slit separation d is:', '["49 μm","4.9 μm","490 μm","0.49 μm"]'::jsonb, 0, 23),
  ('502c974d-2f8a-48df-996f-000000000024'::uuid, 'Young''s Double Slit Experiment', 'The first bright fringe on either side of the central fringe occurs when the path difference equals:', '["λ/2","λ","2λ","3λ"]'::jsonb, 1, 24),
  ('502c974d-2f8a-48df-996f-000000000025'::uuid, 'Interference in Thin Films', 'Oil spills and soap bubbles show bright colours because of:', '["Diffraction","Scattering","Interference between light reflected from the front and back surfaces","Polarization"]'::jsonb, 2, 25),
  ('502c974d-2f8a-48df-996f-000000000026'::uuid, 'Interference in Thin Films', 'A reflected wave gets a phase shift of π when it reflects from a medium that has:', '["A higher refractive index than the first medium","A lower refractive index than the first medium","The same refractive index","No refractive index"]'::jsonb, 0, 26),
  ('502c974d-2f8a-48df-996f-000000000027'::uuid, 'Interference in Thin Films', 'The extra optical path made by the wave reflected from the back surface of a film of optical thickness nt is:', '["nt","2nt","t/n","nt/2"]'::jsonb, 1, 27),
  ('502c974d-2f8a-48df-996f-000000000028'::uuid, 'Interference in Thin Films', 'The film appears bright (constructive interference) when nt equals:', '["Even multiples of λ/4","Odd multiples of λ/4","Whole multiples of λ","Zero"]'::jsonb, 1, 28),
  ('502c974d-2f8a-48df-996f-000000000029'::uuid, 'Interference in Thin Films', 'If the optical thickness of the film is 3λ/4, the interference is:', '["Destructive","Constructive","None","Polarization"]'::jsonb, 1, 29),
  ('502c974d-2f8a-48df-996f-000000000030'::uuid, 'Interference in Thin Films', 'If the optical thickness of the film is 2λ/4, the interference is:', '["Constructive","No interference","Destructive","Polarization"]'::jsonb, 2, 30),
  ('502c974d-2f8a-48df-996f-000000000031'::uuid, 'Interference in Thin Films', 'The wavelength of light in a medium of refractive index n is:', '["λ·n","λ/n","n/λ","λ − n"]'::jsonb, 1, 31),
  ('502c974d-2f8a-48df-996f-000000000032'::uuid, 'Diffraction by a Single Slit and a Grating', 'In single-slit diffraction, the dark-fringe condition is:', '["ℓ sinθ = (m + ½)λ","ℓ sinθ = mλ","ℓ sinθ = λ/2","ℓ sinθ = 0 only"]'::jsonb, 1, 32),
  ('502c974d-2f8a-48df-996f-000000000033'::uuid, 'Diffraction by a Single Slit and a Grating', 'For the first non-central bright fringe, the slit width is:', '["λ/(2 sinθ)","3λ/(2 sinθ)","λ/sinθ","2λ/sinθ"]'::jsonb, 1, 33),
  ('502c974d-2f8a-48df-996f-000000000034'::uuid, 'Diffraction by a Single Slit and a Grating', 'In single-slit diffraction, the intensity of the bright fringes as you move away from the centre:', '["Increases","Decreases","Stays constant","Doubles"]'::jsonb, 1, 34),
  ('502c974d-2f8a-48df-996f-000000000035'::uuid, 'Diffraction by a Single Slit and a Grating', 'If the slit width is reduced, the central bright fringe becomes:', '["Narrower","Wider and less bright","Unchanged","Non-existent"]'::jsonb, 1, 35),
  ('502c974d-2f8a-48df-996f-000000000036'::uuid, 'Diffraction by a Single Slit and a Grating', 'Light and dark fringes seen when looking at a lamp through two nearly closed fingers are due to:', '["Reflection","Diffraction","Polarization","Scattering"]'::jsonb, 1, 36),
  ('502c974d-2f8a-48df-996f-000000000037'::uuid, 'Diffraction by a Single Slit and a Grating', 'A grating has 5000 lines/cm. The grating constant is:', '["2×10⁻⁴ cm","5×10⁻³ cm","2×10⁻³ cm","5×10⁻⁴ cm"]'::jsonb, 0, 37),
  ('502c974d-2f8a-48df-996f-000000000038'::uuid, 'Diffraction by a Single Slit and a Grating', 'The bright-fringe condition for a diffraction grating is:', '["d sinθ = (m + ½)λ","d sinθ = mλ","d cosθ = mλ","d = mλ sinθ"]'::jsonb, 1, 38),
  ('502c974d-2f8a-48df-996f-000000000039'::uuid, 'Diffraction by a Single Slit and a Grating', 'When the grating constant decreases, the diffraction angle of a given fringe:', '["Decreases","Increases","Stays unchanged","Becomes zero"]'::jsonb, 1, 39),
  ('502c974d-2f8a-48df-996f-000000000040'::uuid, 'Diffraction by a Single Slit and a Grating', 'Laser light (632.8 nm) falls on a grating with 6000 lines/cm. The angle of the first bright fringe is about:', '["49°","7.5°","21.3°","38°"]'::jsonb, 2, 40),
  ('502c974d-2f8a-48df-996f-000000000041'::uuid, 'Diffraction by a Single Slit and a Grating', 'A grating has 2000 lines/cm and red light of 640 nm is used. The first-order angle is about (sin 7.5° = 0.128):', '["7.5°","12.8°","0.128°","15°"]'::jsonb, 0, 41),
  ('502c974d-2f8a-48df-996f-000000000042'::uuid, 'Diffraction by a Single Slit and a Grating', 'When green light is used with a diffraction grating, the central fringe appears:', '["Yellow","Red","Green","White"]'::jsonb, 2, 42),
  ('502c974d-2f8a-48df-996f-000000000043'::uuid, 'Diffraction by a Single Slit and a Grating', 'A diffraction grating is useful for:', '["Studying spectra","Analysing light sources","Measuring the wavelength of light","All of the above"]'::jsonb, 3, 43),
  ('502c974d-2f8a-48df-996f-000000000044'::uuid, 'Polarization', 'Longitudinal waves cannot show:', '["Refraction","Reflection","Diffraction","Polarization"]'::jsonb, 3, 44),
  ('502c974d-2f8a-48df-996f-000000000045'::uuid, 'Polarization', 'In unpolarized light, the electric field vibrates:', '["In one plane only","In all directions perpendicular to the propagation direction","Parallel to the propagation direction","Not at all"]'::jsonb, 1, 45),
  ('502c974d-2f8a-48df-996f-000000000046'::uuid, 'Polarization', 'Polarized light is light whose electric field vibration is:', '["In many directions","In all directions","Limited to one direction perpendicular to the propagation line","Parallel to the propagation line"]'::jsonb, 2, 46),
  ('502c974d-2f8a-48df-996f-000000000047'::uuid, 'Polarization', 'In the tourmaline activity, the second slice is called the:', '["Polarizer","Analyzer","Grating","Collimator"]'::jsonb, 1, 47),
  ('502c974d-2f8a-48df-996f-000000000048'::uuid, 'Polarization', 'The light passing through a polarizer and an analyzer disappears completely when the angle between their transmission axes is:', '["0°","45°","60°","90°"]'::jsonb, 3, 48),
  ('502c974d-2f8a-48df-996f-000000000049'::uuid, 'Polarization', 'The two main methods of polarizing light are:', '["Selective absorption and reflection","Refraction only","Diffraction only","Scattering"]'::jsonb, 0, 49),
  ('502c974d-2f8a-48df-996f-000000000050'::uuid, 'Polarization', 'Which of these are optically active materials?', '["Air and vacuum","Glass and water","Quartz crystal and sugar solution","Copper and iron"]'::jsonb, 2, 50),
  ('502c974d-2f8a-48df-996f-000000000051'::uuid, 'Polarization', 'The angle of optical rotation depends on:', '["Type of material and its thickness","Concentration of the solution","Wavelength of the light","All of the above"]'::jsonb, 3, 51),
  ('502c974d-2f8a-48df-996f-000000000052'::uuid, 'Polarization', 'The relation between the polarization (Brewster) angle and the refractive index is:', '["sinθp = n","tanθp = n","cosθp = n","θp = n"]'::jsonb, 1, 52),
  ('502c974d-2f8a-48df-996f-000000000053'::uuid, 'Polarization', 'Light is totally polarized on reflection when the incidence angle is 48° (tan 48° = 1.110). The refractive index of the medium is:', '["0.9","1.110","1.48","48"]'::jsonb, 1, 53),
  ('502c974d-2f8a-48df-996f-000000000054'::uuid, 'Polarization', 'The critical angle of blue agate in air is 34.4° (n = 1.77, tan 60.5° = 1.77). Its polarization angle is:', '["34.4°","55.5°","60.5°","1.77°"]'::jsonb, 2, 54),
  ('502c974d-2f8a-48df-996f-000000000055'::uuid, 'Polarization', 'At the Brewster angle, the angle between the reflected and refracted rays is:', '["0°","45°","90°","180°"]'::jsonb, 2, 55),
  ('502c974d-2f8a-48df-996f-000000000056'::uuid, 'Polarization', 'If the angle of incidence is zero, light reflected from a surface shows:', '["Total polarization","No polarization","Partial polarization","Double refraction"]'::jsonb, 1, 56),
  ('502c974d-2f8a-48df-996f-000000000057'::uuid, 'Scattering of Light', 'The intensity of scattered light is proportional to:', '["λ","1/λ","1/λ⁴","λ⁴"]'::jsonb, 2, 57),
  ('502c974d-2f8a-48df-996f-000000000058'::uuid, 'Scattering of Light', 'The sky looks blue because:', '["Air particles are blue","The lens of the eye is blue","Short wavelengths are scattered more than long wavelengths","Long wavelengths are scattered more than short wavelengths"]'::jsonb, 2, 58),
  ('502c974d-2f8a-48df-996f-000000000059'::uuid, 'Scattering of Light', 'The sky appears red and orange at sunrise and sunset because:', '["Red light is scattered most","Red and orange light are poorly scattered, so they reach the eye","Blue light is polarized","The sun changes colour"]'::jsonb, 1, 59),
  ('502c974d-2f8a-48df-996f-000000000060'::uuid, 'Scattering of Light', 'An astronaut on the Moon sees a black sky and stars in daylight because:', '["There is no atmosphere to scatter light","The Moon is too far from the sun","The Moon has too much dust","The stars are brighter there"]'::jsonb, 0, 60),
  ('502c974d-2f8a-48df-996f-000000000061'::uuid, 'Scattering of Light', 'Scattering of visible light happens on particles whose diameter is:', '["Much larger than λ","Comparable to or smaller than λ","Zero","Infinite"]'::jsonb, 1, 61)
)
INSERT INTO public.mcq_banks (id, subject, chapter, chapter_title, section, language, question, choices, answer_index, source, sort_order)
SELECT s.id, 'physics', 5, 'Physical Optics', s.section, 'en', s.question, s.choices, s.answer_index,
       'Chapter 5: Physical Optics - MCQ Bank', s.sort_order
FROM seed s
WHERE NOT EXISTS (
  SELECT 1 FROM public.mcq_banks b
  WHERE b.subject = 'physics' AND b.chapter = 5 AND b.language = 'en' AND b.question = s.question
)
ON CONFLICT (id) DO NOTHING;
